17	/**
18	 * Crée une erreur enrichie avec code HTTP.
19	 *
20	 * @param {string} message Message d'erreur.
21	 * @param {number} status Code HTTP.
22	 * @returns {Error & {status?: number}} Erreur enrichie.
23	 */
24	function buildHttpError(message, status) {
25	  const error = new Error(message);
26	  error.status = Number(status || 0);
27	  return error;
28	}
29	
30	/**
31	 * Affiche un message de retour utilisateur dans la page.
32	 *
