46	/**
47	 * Redirige vers la page de connexion Account si la session est absente ou
48	 * invalide (spec ticket 009: "if the response is 401, redirect to the login
49	 * page").
50	 *
51	 * @param {unknown} error Erreur levée par une requête API.
52	 * @returns {boolean} true si redirection déclenchée.
53	 */
54	function redirectToLoginIfUnauthorized(error) {
55	  const status = Number(error?.status || 0);
56	  if (status !== 401) {
57	    return false;
58	  }
59	
60	  window.location.href = new URL("account-login.html", window.location.href).toString();
61	  return true;
62	}
