66	 *
67	 * @param {string} endpoint Route API cible.
68	 * @param {string} actionLabel Libellé de l'action pour les messages d'erreur.
69	 * @returns {Promise<Object>} Réponse JSON du backend.
70	 * @throws {Error} Si la réponse HTTP n'est pas en succès.
71	 */
72	async function getJson(endpoint, actionLabel) {
73	  const response = await fetch(endpoint, {
74	    method: "GET",
75	    headers: {
76	      "Content-Type": "application/json",
77	    },
78	  });
79	
80	  const rawResponse = await response.text();
