103	 *
104	 * @param {string} endpoint Route API cible.
105	 * @param {Object} payload Données JSON envoyées.
106	 * @param {string} actionLabel Libellé de l'action pour les messages d'erreur.
107	 * @returns {Promise<Object>} Réponse JSON du backend.
108	 * @throws {Error} Si la réponse HTTP n'est pas en succès.
109	 */
110	async function postJson(endpoint, payload, actionLabel) {
