140	/**
141	 * Traduit le statut technique d'un Syncer en libellé lisible.
142	 *
143	 * @param {string} status Statut brut ('active'/'archived').
144	 * @returns {string} Libellé français.
145	 */
146	function describeSyncerStatus(status) {
147	  return status === "archived" ? "Archivé" : "Actif";
